// ---- seats

// SeatsUsed returns how many seats an organization uses: its members who are not viewers, plus its pending invites
// (neither accepted nor revoked) whose role is not viewer. Viewers are free.
func (s *Store) SeatsUsed(orgID string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.seatsUsed(orgID)
}

// seatsUsed is SeatsUsed for a caller that holds the lock.
func (s *Store) seatsUsed(orgID string) int {
	n := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role != RoleViewer {
			n++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.Role != RoleViewer && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			n++
		}
	}
	return n
}

// requireSeat returns a SeatLimitError when the organization's plan has no seat left. The caller holds the lock.
func (s *Store) requireSeat(orgID string) error {
	limit, ok := s.orgs[orgID].Plan.SeatLimit()
	if !ok {
		return nil
	}
	if used := s.seatsUsed(orgID); used >= limit {
		return &SeatLimitError{Limit: limit, Used: used}
	}
	return nil
}

