cat >> internal/api/api_test.go <<'EOF'

// seatsOf reads an organization's seats from GET /v1/org.
func seatsOf(t *testing.T, e *apitest.Env, key string) (used int, limit *int) {
	t.Helper()
	var o struct {
		Seats struct {
			Used  int  `json:"used"`
			Limit *int `json:"limit"`
		} `json:"seats"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", key, nil, &o)
	return o.Seats.Used, o.Seats.Limit
}

func TestSeatLimits(t *testing.T) {
	e := apitest.New(t)
	free := e.NewOrg("Free", store.OrgFree, "UTC") // 3 seats
	member, _ := e.AddMember(free, "m@free.example", store.RoleMember)
	viewer, _ := e.AddMember(free, "v@free.example", store.RoleViewer)
	if used, limit := seatsOf(t, e, free.Key); used != 2 || limit == nil || *limit != 3 {
		t.Fatalf("seats = %d of %v, want 2 of 3", used, limit)
	}

	// Owner and member use two seats; the pending member invite takes the third.
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "p@free.example", "role": "member"}, &inv)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "v2@free.example", "role": "viewer"}, nil)
	r := e.Do("POST", "/v1/invites", free.Key, map[string]string{"email": "q@free.example", "role": "admin"})
	if body := r.Map(t); r.Code != http.StatusPaymentRequired || body["error"] != "seat_limit_reached" || body["limit"] != float64(3) || body["used"] != float64(3) {
		t.Fatalf("a full org's invite: %s", r)
	}

	// Revoking the pending invite frees its seat.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+inv.ID, free.Key, nil, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "p@free.example", "role": "member"}, &inv)

	// Accepting an invite never needs a seat: the invite already holds one.
	msgs := e.Mail.Messages()
	m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[len(msgs)-1].Body)
	if m == nil {
		t.Fatalf("no link in %q", msgs[len(msgs)-1].Body)
	}
	token, _ := url.QueryUnescape(m[1])
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "P"}, nil)
	if used, _ := seatsOf(t, e, free.Key); used != 3 {
		t.Fatalf("seats used after accepting = %d, want 3", used)
	}

	// The org is full, but a viewer's invite and a role change to viewer still work.
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "v3@free.example", "role": "viewer"}, nil)
	r = e.Do("PATCH", "/v1/members/"+viewer.ID, free.Key, map[string]string{"role": "member"})
	if body := r.Map(t); r.Code != http.StatusPaymentRequired || body["error"] != "seat_limit_reached" || body["used"] != float64(3) {
		t.Fatalf("a viewer gets a seat in a full org: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+member.ID, free.Key, map[string]string{"role": "viewer"}, nil)
	if used, _ := seatsOf(t, e, free.Key); used != 2 {
		t.Fatalf("seats used after a member became a viewer = %d, want 2", used)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+viewer.ID, free.Key, map[string]string{"role": "member"}, nil)
	if used, _ := seatsOf(t, e, free.Key); used != 3 {
		t.Fatalf("seats used after a viewer got a seat = %d, want 3", used)
	}

	// Downgrading to a plan with fewer seats than are in use is refused, and changes nothing.
	for i := range 3 {
		e.AddMember(e.Globex, fmt.Sprintf("g%d@globex.example", i), store.RoleMember)
	}
	if used, limit := seatsOf(t, e, e.Globex.Key); used != 4 || limit != nil {
		t.Fatalf("business seats = %d of %v, want 4 of unlimited", used, limit)
