	}
	r = e.Do("PATCH", "/v1/org", e.Globex.Key, map[string]any{"name": "Renamed", "plan": "free"})
	if body := r.Map(t); r.Code != http.StatusConflict || body["error"] != "over_seat_limit" || body["limit"] != float64(3) || body["used"] != float64(4) {
		t.Fatalf("downgrade over the seats: %s", r)
	}
	var o store.Org
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Globex.Key, nil, &o)
	if o.Name != "Globex" || o.Plan != store.OrgBusiness {
		t.Fatalf("org after a refused change = %+v", o)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Globex.Key, map[string]any{"plan": "team"}, nil)
	if used, limit := seatsOf(t, e, e.Globex.Key); used != 4 || limit == nil || *limit != 10 {
		t.Fatalf("team seats = %d of %v, want 4 of 10", used, limit)
	}
}

// With one seat left, invites sent at the same time: exactly one succeeds.
func TestSeatLimitHoldsUnderConcurrency(t *testing.T) {
	e := apitest.New(t)
	free := e.NewOrg("Race", store.OrgFree, "UTC")
	e.AddMember(free, "m@race.example", store.RoleMember) // owner and member: two of three seats
	const senders = 8
	codes := make([]int, senders)
	var wg sync.WaitGroup
	for i := range senders {
		wg.Add(1)
		go func() {
			defer wg.Done()
			codes[i] = e.Do("POST", "/v1/invites", free.Key, map[string]string{"email": fmt.Sprintf("p%d@race.example", i), "role": "member"}).Code
		}()
	}
	wg.Wait()
	created := 0
	for _, c := range codes {
		switch c {
		case http.StatusCreated:
			created++
		case http.StatusPaymentRequired:
		default:
			t.Fatalf("an invite answered %d", c)
		}
	}
	if created != 1 {
		t.Fatalf("%d of %d concurrent invites succeeded, want 1", created, senders)
	}
	if used, _ := seatsOf(t, e, free.Key); used != 3 {
		t.Fatalf("seats used = %d, want 3", used)
	}
}

